// portrait.js: Ben's portrait as interactive ASCII on the home hero
// (builtin/site). lib.rs puts <canvas class="portrait"> in the hero; this
// finds it, draws the portrait as rows of monospace characters, and reacts:
// a lens follows the pointer (it magnifies and sharpens what's under it), a
// click or tap sends a ripple through the characters, and letters of his name
// surface now and then while it idles. Reduced motion: a still portrait (the
// lens still follows, without animation). Decorative: the canvas is
// aria-hidden; the page's text is the content.
//
// The photo is baked into GRID: 192x192 bytes (0 = background, else
// brightness), from his profile photo with the background removed and the
// tones equalized over the figure.
(function () {
  "use strict";
  var N = 192;
  var GRID = (function (b64) {
    var s = atob(b64), a = new Uint8Array(s.length);
    for (var i = 0; i < s.length; i++) a[i] = s.charCodeAt(i);
    return a;
  })("");
  var RAMP = " .,:;-=+icoxaO0#%@";
  var NAME = "BENPRIDDY";
  var reduce = matchMedia("(prefers-reduced-motion: reduce)");

  function sample(u, v) { // bilinear, u and v in 0..1; -1 outside the figure
    var x = u * (N - 1), y = v * (N - 1);
    if (x < 0 || y < 0 || x > N - 1 || y > N - 1) return -1;
    var x0 = x | 0, y0 = y | 0, x1 = Math.min(N - 1, x0 + 1), y1 = Math.min(N - 1, y0 + 1), fx = x - x0, fy = y - y0;
    var a = GRID[y0 * N + x0], b = GRID[y0 * N + x1], c = GRID[y1 * N + x0], d = GRID[y1 * N + x1];
    if (!a && !b && !c && !d) return -1;
    return ((a * (1 - fx) + b * fx) * (1 - fy) + (c * (1 - fx) + d * fx) * fy) / 255;
  }
  function hash(x, y, t) {
    var h = Math.imul(x * 374761393 + y * 668265263 + t * 2246822519, 3266489917);
    h ^= h >>> 15;
    return (h >>> 0) / 4294967296;
  }

  function Portrait(cv) {
    var ctx = cv.getContext("2d");
    var W = 0, H = 0, dpr = 1, font = 10, cw = 6, lh = 12, cols = 0, rows = 0;
    var colors = { base: "#A8A398", lit: "#ECE8DF", accent: "#FF5B1F" };
    var ptr = { x: -1e4, y: -1e4, sx: -1e4, sy: -1e4, on: 0, son: 0 };
    var ripples = [], raf = 0, visible = true, start = performance.now(), alive = true;

    var light = false;
    function readColors() {
      light = matchMedia("(prefers-color-scheme: light)").matches;
      var cs = getComputedStyle(document.documentElement);
      colors.base = cs.getPropertyValue("--fg-2").trim() || colors.base;
      colors.lit = cs.getPropertyValue("--fg").trim() || colors.lit;
      colors.accent = cs.getPropertyValue("--accent").trim() || colors.accent;
    }
    function size() {
      var r = cv.getBoundingClientRect();
      dpr = Math.min(window.devicePixelRatio || 1, 2);
      W = Math.max(1, Math.round(r.width)); H = Math.max(1, Math.round(r.height));
      cv.width = Math.round(W * dpr); cv.height = Math.round(H * dpr);
      // a fixed character size: a bigger portrait gets more lines, not bigger letters
      cw = W < 600 ? 4.6 : 6; cols = Math.floor(W / cw); cw = W / cols; lh = cw * 2; rows = Math.floor(H / lh);
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      // size the font so one character advances exactly cw (browsers differ in the mono they end up with)
      ctx.font = '100px "Fragment Mono", ui-monospace, Menlo, monospace';
      var adv = ctx.measureText("MMMMMMMMMM").width / 10 / 100 || 0.6;
      font = cw / adv;
      ctx.font = font.toFixed(2) + 'px "Fragment Mono", ui-monospace, Menlo, monospace';
      ctx.textBaseline = "top";
      kick();
    }

    function frame(now) {
      raf = 0;
      if (!alive) return;
      var t = (now - start) / 1000, calm = reduce.matches;
      // the lens eases after the pointer
      var k = calm ? 1 : 0.18;
      ptr.sx += (ptr.x - ptr.sx) * k; ptr.sy += (ptr.y - ptr.sy) * k; ptr.son += (ptr.on - ptr.son) * k;
      ripples = ripples.filter(function (r) { return t - r.t < 1.6; });
      var R = Math.min(W, H) * 0.2, rev = calm ? rows : Math.min(rows, (t / 1.1) * rows); // entrance: rows resolve top-down
      var tick = Math.floor(t * 7);
      ctx.clearRect(0, 0, W, H);
      for (var j = 0; j < rows; j++) {
        var base = "", lit = "", acc = "", anyLit = false, anyAcc = false;
        var cy = (j + 0.5) * lh;
        for (var i = 0; i < cols; i++) {
          var cx = (i + 0.5) * cw, u = cx / W, v = cy / H;
          var dx = cx - ptr.sx, dy = cy - ptr.sy, d = Math.sqrt(dx * dx + dy * dy);
          var lens = ptr.son * Math.max(0, 1 - d / R);
          if (lens > 0) { // magnify: sample nearer the lens centre
            var m = 1 - 0.35 * lens * lens;
            u = (ptr.sx + dx * m) / W; v = (ptr.sy + dy * m) / H;
          }
          var s = sample(u, v), ch = " ", kind = 0;
          if (s >= 0) {
            var b = s;
            if (lens > 0) b = Math.min(1, 0.5 + (b - 0.5) * (1 + 0.9 * lens) + 0.12 * lens); // sharper under the lens
            // ink, not light: on the day theme the letters are dark on paper, so density follows the photo's darks
            if (light) b = 1 - (b < 0 ? 0 : b > 1 ? 1 : b);
            for (var q = 0; q < ripples.length; q++) { // a ring of light running outward
              var rp = ripples[q], age = t - rp.t, rr = age * Math.max(W, H) * 0.75;
              var dd = Math.abs(Math.sqrt((cx - rp.x) * (cx - rp.x) + (cy - rp.y) * (cy - rp.y)) - rr);
              if (dd < lh * 1.4) { b = Math.min(1, b + (1 - dd / (lh * 1.4)) * (1 - age / 1.6) * 0.8); kind = 2; }
            }
            b = b < 0 ? 0 : b > 1 ? 1 : b;
            ch = RAMP[Math.min(RAMP.length - 1, 1 + Math.floor(b * (RAMP.length - 1)))];
            if (!calm && hash(i, j, tick) < 0.0025) { ch = NAME[(i + j) % NAME.length]; kind = 2; }
            if (j > rev) ch = " ";
            else if (j > rev - 2 && !calm) { ch = RAMP[1 + Math.floor(hash(i, j, tick) * (RAMP.length - 1))]; }
            if (kind !== 2 && lens > 0.25) kind = 1;
          }
          base += kind === 0 ? ch : " ";
          lit += kind === 1 ? ch : " ";
          acc += kind === 2 ? ch : " ";
          if (kind === 1) anyLit = true; else if (kind === 2) anyAcc = true;
        }
        var y = j * lh + (lh - font) / 2;
        ctx.fillStyle = colors.base; ctx.fillText(base, 0, y);
        if (anyLit) { ctx.fillStyle = colors.lit; ctx.fillText(lit, 0, y); }
        if (anyAcc) { ctx.fillStyle = colors.accent; ctx.fillText(acc, 0, y); }
      }
      var busy = !calm && (t < 1.4 || ripples.length || Math.abs(ptr.x - ptr.sx) + Math.abs(ptr.y - ptr.sy) > 0.5 || Math.abs(ptr.on - ptr.son) > 0.01);
      // idle: the name's letters keep surfacing, a few times a second
      if (visible && !document.hidden) {
        if (busy) raf = requestAnimationFrame(frame);
        else if (!calm) idle = setTimeout(kick, 140);
      }
    }
    var idle = 0;
    function kick() {
      clearTimeout(idle);
      if (!raf && alive && visible && !document.hidden) raf = requestAnimationFrame(frame);
    }

    function local(e) { var r = cv.getBoundingClientRect(); return [e.clientX - r.left, e.clientY - r.top, r]; }
    function onMove(e) {
      var p = local(e), r = p[2];
      var inside = p[0] > -40 && p[1] > -40 && p[0] < r.width + 40 && p[1] < r.height + 40;
      ptr.x = p[0]; ptr.y = p[1]; ptr.on = inside ? 1 : 0;
      if (ptr.sx < -1e3) { ptr.sx = ptr.x; ptr.sy = ptr.y; }
      kick();
    }
    function onDown(e) {
      var p = local(e), r = p[2];
      if (p[0] < 0 || p[1] < 0 || p[0] > r.width || p[1] > r.height) return;
      if (e.target && e.target.closest && e.target.closest("a, button")) return;
      if (!reduce.matches) ripples.push({ x: p[0], y: p[1], t: (performance.now() - start) / 1000 });
      onMove(e);
    }
    function onLeave() { ptr.on = 0; kick(); }
    window.addEventListener("pointermove", onMove, { passive: true });
    window.addEventListener("pointerdown", onDown, { passive: true });
    document.addEventListener("pointerleave", onLeave);
    var ro = new ResizeObserver(size); ro.observe(cv);
    var io = new IntersectionObserver(function (es) { visible = es[0].isIntersecting; kick(); });
    io.observe(cv);
    var scheme = matchMedia("(prefers-color-scheme: light)");
    function onScheme() { readColors(); kick(); }
    scheme.addEventListener("change", onScheme);
    document.addEventListener("visibilitychange", kick);
    readColors();
    if (document.fonts && document.fonts.load) document.fonts.load('10px "Fragment Mono"').then(size, size); else size();

    this.destroy = function () {
      alive = false; clearTimeout(idle); if (raf) cancelAnimationFrame(raf);
      window.removeEventListener("pointermove", onMove); window.removeEventListener("pointerdown", onDown);
      document.removeEventListener("pointerleave", onLeave); document.removeEventListener("visibilitychange", kick);
      scheme.removeEventListener("change", onScheme); ro.disconnect(); io.disconnect();
    };
  }

  // the hero is rebuilt on every visit to the home route: attach to each new canvas
  var current = null, currentCv = null;
  function scan() {
    var cv = document.querySelector("canvas.portrait");
    if (cv === currentCv) return;
    if (current) current.destroy();
    current = null; currentCv = cv;
    if (cv) {
      try { current = new Portrait(cv); } catch (err) { if (window.site && site.reportError) site.reportError(err); }
    }
  }
  new MutationObserver(scan).observe(document.documentElement, { childList: true, subtree: true });
  scan();
})();
